&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;🚀&lt;/span&gt;&lt;/span&gt; &lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;Real responsibility on hard problems, with the autonomy to own decisions and act on them, in an open culture built on trust.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559685&amp;quot;:426,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559991&amp;quot;:426,&amp;quot;469777462&amp;quot;:[852],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;🏡&lt;/span&gt;&lt;/span&gt; &lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;Flexible working arrangements that allow remote work or office attendance &lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559685&amp;quot;:426,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559991&amp;quot;:426,&amp;quot;469777462&amp;quot;:[852],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;💰&lt;/span&gt;&lt;/span&gt; &lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;An attractive compensation and benefits package, including private health insurance, a company bonus scheme and enhanced pension scheme &lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559685&amp;quot;:426,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559991&amp;quot;:426,&amp;quot;469777462&amp;quot;:[852],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;🏖️&lt;/span&gt;&lt;/span&gt; &lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;25 days holiday plus bank holidays, and a day off during your birthday month  &lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559685&amp;quot;:426,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559991&amp;quot;:426,&amp;quot;469777462&amp;quot;:[852],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;⚡&lt;/span&gt;&lt;/span&gt; &lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;Octopus EV salary sacrifice scheme &lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559685&amp;quot;:426,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559991&amp;quot;:426,&amp;quot;469777462&amp;quot;:[852],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
